/***
 * MARK: scoreWord
 * @description Scores one index entry against a single normalized word: 3 for
 *   a label prefix match, 2 for a label substring, 1 for a keyword
 *   substring, 0 for no match. Scores rank `searchSettings` so label hits
 *   lead. A non-array `keywords` field scores 0 instead of throwing.
 * @example scoreWord({ label: 'Git Repository URL', keywords: ['git'] }, 'git') => 3
 * @param {Object} entry - One `SETTINGS_SEARCH_INDEX` entry.
 * @param {string} word - Lowercase query word.
 * @returns {number} Match score (0 = no match).
 ***/
const scoreWord = (entry, word) => {
  const label = String(entry?.label ?? '').toLowerCase();
  if (label.startsWith(word)) return 3;
  if (label.includes(word)) return 2;
  const keywords = Array.isArray(entry?.keywords) ? entry.keywords : [];
  if (keywords.some((keyword) => String(keyword).toLowerCase().includes(word))) return 1;
  return 0;
};

/***
 * MARK: searchSettings
 * @description Returns index entries matching a query (case-insensitive).
 *   Multi-word queries match when EVERY word hits (label substring or
 *   keyword substring), so "centralised docs folder" finds the docs-link
 *   setting however the words are ordered. Scores sum the per-word best
 *   hits, best matches first with index order breaking ties. Blank queries
 *   and non-matches return an empty array.
 * @example searchSettings('git') => [{ id: 'git-repo', tab: 'files', … }]
 * @param {string} query - Raw user input.
 * @returns {Array<Object>} Matching entries, ranked best-first.
 ***/
export const searchSettings = (query) => {
  const normalized = String(query ?? '')
    .trim()
    .toLowerCase();
  if (!normalized) return [];
  const words = normalized.split(/\s+/).filter(Boolean);
  return SETTINGS_SEARCH_INDEX.map((entry, index) => {
    let score = 0;
    for (const word of words) {
      const wordScore = scoreWord(entry, word);
      // One missed word disqualifies the entry (AND semantics).
      if (wordScore === 0) return null;
      score += wordScore;
    }
    return { entry, score, index };
  })
    .filter((hit) => hit !== null)
    .sort((first, second) => second.score - first.score || first.index - second.index)
    .map((hit) => hit.entry);
};

/***
 * MARK: findBestMatch
 * @description Returns the single best index entry for a query (for
 *   jump-on-Enter), or null when nothing matches.
 * @example findBestMatch('git') => { id: 'git-repo', tab: 'files', … }
 * @param {string} query - Raw user input.
 * @returns {Object|null} The best matching entry, if any.
 ***/
export const findBestMatch = (query) => searchSettings(query)[0] ?? null;

import { useEffect, useRef, useState } from 'react';
import { searchSettings } from './projectSettingsSearch';

/***
 * MARK: SettingsSearchInput
 * @description Search box for the Project Settings tab bar: typing shows up
 *   to 8 matching settings (label + tab name), `↑`/`↓` moves the highlight,
 *   `Enter` jumps to the highlighted match, `Escape` or clicking outside
 *   closes the dropdown. Choosing a result calls `onSelect` with the index
 *   entry; the parent switches tabs and highlights the setting.
 * @example <SettingsSearchInput onSelect={(entry) => jumpTo(entry)} />
 * @param {Object} props
 * @param {Function} props.onSelect - Called with the chosen index entry.
 ***/
export function SettingsSearchInput({ onSelect }) {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(0);
  const rootRef = useRef(null);
  const results = query.trim() ? searchSettings(query).slice(0, 8) : [];
  const activeEntry = results[Math.min(activeIndex, Math.max(results.length - 1, 0))] ?? null;

  // Clicking outside closes the dropdown.
  useEffect(() => {
    if (!open) return undefined;
    const onDocMouseDown = (event) => {
      if (rootRef.current && !rootRef.current.contains(event.target)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDocMouseDown);
    return () => document.removeEventListener('mousedown', onDocMouseDown);
  }, [open ]);

  const choose = (entry) => {
    if (!entry) return;
    setOpen(false);
    setQuery('');
    onSelect?.(entry);
  };

  const onKeyDown = (event) => {
    if (event.key === 'ArrowDown' && results.length > 0) {
      event.preventDefault();
      setOpen(true);
      setActiveIndex((index) => (index + 1) % results.length);
    } else if (event.key === 'ArrowUp' && results.length > 0) {
      event.preventDefault();
      setOpen(true);
      setActiveIndex((index) => (index - 1 + results.length) % results.length);
    } else if (event.key === 'Enter') {
      // Jump even when the dropdown was dismissed (Escape or click-outside):
      // the text still names the top result, so Enter follows it instead of
      // doing nothing. With an empty query there is no result — no-op.
      if (activeEntry) {
        event.preventDefault();
        choose(activeEntry);
      }
    } else if (event.key === 'Escape') {
      setOpen(false);
    }
  };

  return (
    <div ref={rootRef} className="relative">
      <input
        type="text"
        role="combobox"
        aria-expanded={open && results.length > 0}
        aria-controls="project-settings-search-listbox"
        aria-activedescendant={open && activeEntry ? `project-settings-search-option-${activeEntry.id}` : undefined}
        aria-label="Search settings"
        placeholder="Search settings…"
        value={query}
        onChange={(event) => {
          setQuery(event.target.value);
          // A new query restarts navigation at the top result.
          setActiveIndex(0);
          setOpen(true);
        }}
        onFocus={() => {
          if (query.trim()) setOpen(true);
        }}
        onKeyDown={onKeyDown}
        className="p-2 bg-surface-container border border-border-standard rounded-sm text-xs outline-none focus:border-primary transition-colors text-on-surface placeholder:text-text-muted w-44"
      />
      {open && results.length > 0 && (
        <ul
          id="project-settings-search-listbox"
          role="listbox"
          aria-label="Matching settings"
          className="absolute right-0 mt-1 w-64 max-h-64 overflow-y-auto custom-scrollbar bg-surface-container border border-border-standard rounded-sm shadow-lg z-10 py-1"
        >
          {results.map((entry, index) => (
            <li
              key={entry.id}
              id={`project-settings-search-option-${entry.id}`}
              role="option"
              aria-selected={index === activeIndex}
            >
              <button
                type="button"
                onMouseDown={(event) => {
                  // Fires before the input's blur closes the dropdown.
                  event.preventDefault();
                  choose(entry);
                }}
                onMouseEnter={() => setActiveIndex(index)}
                className={`w-full text-left px-3 py-1.5 flex items-center justify-between gap-2 cursor-pointer ${
                  index === activeIndex
                    ? 'bg-primary/15 text-on-surface'
                    : 'text-text-muted hover:text-on-surface'
                }`}
              >
                <span className="text-xs font-medium truncate">{entry.label}</span>
                <span className="text-[10px] uppercase tracking-wider shrink-0">
                  {entry.tabLabel}
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
